#!/usr/bin/env python3
"""Build local 32px connection icons as packed 4-bit coverage (host only)."""
import hashlib,io,json
from pathlib import Path
import cairosvg
from PIL import Image
ROOT=Path(__file__).resolve().parents[1]

def main():
    out=['#pragma once\n#include <cstdint>\n#ifdef ARDUINO\n#include <pgmspace.h>\n#else\n#ifndef PROGMEM\n#define PROGMEM\n#endif\n#endif\n',
         '// Generated by scripts/build_connection_icons.py from local MIT SVGs.\n',
         '// Sources, hashes and licenses: assets/icons/connection-icons.json.\n',
         'namespace ConnectionAssets {\n']
    names={'andrsrxn:usb':'Usb','andrsrxn:bluetooth':'Bluetooth','boxicons:monitor-wide':'Mpd'}
    total=0
    for spec in json.loads((ROOT/'assets/icons/connection-icons.json').read_text()):
        svg=(ROOT/'assets/icons'/spec['file']).read_bytes()
        assert hashlib.sha256(svg).hexdigest()==spec['sha256'],spec['file']
        for size in (32,):
            png=cairosvg.svg2png(bytestring=svg.replace(b'currentColor',b'#ffffff'),output_width=size,output_height=size)
            alpha=Image.open(io.BytesIO(png)).convert('RGBA').getchannel('A')
            pixels=[min(15,(value+8)//17) for value in alpha.getdata()]
            packed=bytes((pixels[i]<<4)|pixels[i+1] for i in range(0,len(pixels),2))
            out.append(f'const uint8_t k{names[spec["icon"]]}{size}[] PROGMEM = {{\n')
            for i in range(0,len(packed),24):out.append(' '+','.join(f'0x{x:02x}' for x in packed[i:i+24])+',\n')
            out.append('};\n');total+=len(packed)
    out.append('}\n');(ROOT/'firmware/include/connection_assets.h').write_text(''.join(out))
    print('Connection icons:',total,'bytes of packed coverage, no runtime SVG/font dependency')

if __name__=='__main__':main()
